/**
 * Modified from:
 * uvx --from git+https://github.com/tpircher/pycrc pycrc
 * --generate=c --algorithm=table-driven --width=10 --poly=0x48F --xor-in=0x10
 * --xor-out=0 --reflect-in=false --reflect-out=false
 */
// NOLINTNEXTLINE (bugprone-easily-swappable-parameters)
uint_fast16_t pec_10_crc(uint8_t const *data, size_t byte_len,
                         size_t extra_bit_len) {
  uint_fast16_t crc = 0x10;
  uint8_t tbl_idx;

  while (byte_len--) {
    tbl_idx = (crc >> 2) ^ *(data++);
    crc = (crc_table[tbl_idx] ^ (crc << 8)) & 0x3ff;
  }

  if (extra_bit_len) {
    // * instead of crc>>(CRC_WIDTH-8) we have crc>>(CRC_WIDTH-extra_bit_len)
    // * instead of *data we have (*data)>>8-extra_bit_len bc the rest of the
    //   function expects the data array to be in MSByte order, so the extra
    //   bits are also in the MSBit portion of the byte
    tbl_idx =
        (crc >> (10 - extra_bit_len)) ^ (*(data++) >> (8 - extra_bit_len));
    // * instead of crc<<8 we have crc<<extra_bit_len
    // * the (1<<CRC_WIDTH)-1 mask is kept as is
    crc = (crc_table[tbl_idx] ^ (crc << extra_bit_len)) & 0x3ff;
  }
  return crc;
}
